{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-193jzP/src/path.js","content":"/**
 * Path segments identify a node in the document, either an object key (`k`)
 * or an array index (`i`). Both the `keys` output and error messages that
 * name a path share this representation and formatting.
 */

export function keySeg(name) {
  return { t: 'k', v: name }
}

export function indexSeg(i) {
  return { t: 'i', v: i }
}

export function pathToString(segments) {
  let out = ''
  for (const seg of segments) {
    if (seg.t === 'k') {
      out += out === '' ? seg.v : `.${seg.v}`
    } else {
      out += `[${seg.v}]`
    }
  }
  return out
}

/** Ascending order by Unicode code point, as required for object members. */
export function codePointCompare(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}
"}

