{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-193jzP/src/parser.js","content":"/**
 * Parses a configuration document into a tree of nodes. Every node has a
 * `kind`: `table`, `aot` (array of tables), `array`, `string`, `integer`,
 * `float` or `boolean`. Tables hold their members in a `Map` keyed by the
 * decoded name text, so member order is whatever `format.js` chooses when it
 * walks them rather than insertion order.
 */
import { ParseError } from './errors.js'
import { keySeg, indexSeg, pathToString } from './path.js'

const INT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/

function newTable() {
  return { kind: 'table', entries: new Map(), headerOpened: false }
}

function isNameChar(c) {
  return c !== undefined && /[A-Za-z0-9_-]/.test(c)
}

function skipWS(cur) {
  while (cur.pos < cur.line.length && (cur.line[cur.pos] === ' ' || cur.line[cur.pos] === '\t')) {
    cur.pos++
  }
}

function parseBasicString(cur) {
  cur.pos++ // opening quote
  let out = ''
  for (;;) {
    if (cur.pos >= cur.line.length) throw new ParseError(cur.lineNo, 'unterminated string')
    const c = cur.line[cur.pos]
    if (c === '"') {
      cur.pos++
      return out
    }
    if (c === '\\') {
      cur.pos++
      if (cur.pos >= cur.line.length) throw new ParseError(cur.lineNo, 'unterminated string')
      const e = cur.line[cur.pos]
      if (e === '"') {
        out += '"'
        cur.pos++
      } else if (e === '\\') {
        out += '\\'
        cur.pos++
      } else if (e === 'n') {
        out += '\n'
        cur.pos++
      } else if (e === 't') {
        out += '\t'
        cur.pos++
      } else if (e === 'r') {
        out += '\r'
        cur.pos++
      } else if (e === '0') {
        out += '\0'
        cur.pos++
      } else if (e === 'u') {
        const hex = cur.line.slice(cur.pos + 1, cur.pos + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          cur.pos += 5
        } else {
          throw new ParseError(cur.lineNo, 'invalid escape \\u')
        }
      } else {
        throw new ParseError(cur.lineNo, `invalid escape \\${e}`)
      }
    } else {
      out += c
      cur.pos++
    }
  }
}

function parseLiteralString(cur) {
  cur.pos++ // opening quote
  const start = cur.pos
  for (;;) {
    if (cur.pos >= cur.line.length) throw new ParseError(cur.lineNo, 'unterminated string')
    if (cur.line[cur.pos] === "'") {
      const s = cur.line.slice(start, cur.pos)
      cur.pos++
      return s
    }
    cur.pos++
  }
}

function parseName(cur) {
  skipWS(cur)
  const c = cur.line[cur.pos]
  if (c === '"') return parseBasicString(cur)
  if (c === "'") return parseLiteralString(cur)
  const start = cur.pos
  while (cur.pos < cur.line.length && isNameChar(cur.line[cur.pos])) cur.pos++
  if (cur.pos === start) throw new ParseError(cur.lineNo, 'expected a name')
  return cur.line.slice(start, cur.pos)
}

function parseDottedName(cur) {
  const names = [parseName(cur)]
  for (;;) {
    skipWS(cur)
    if (cur.line[cur.pos] === '.') {
      cur.pos++
      skipWS(cur)
      names.push(parseName(cur))
    } else {
      break
    }
  }
  return names
}

function isValueTerminator(c) {
  return c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}'
}

function interpretBareword(token, lineNo) {
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) {
    let text = token.replace(/_/g, '')
    if (text[0] === '+') text = text.slice(1)
    return { kind: 'integer', value: text }
  }
  if (FLOAT_RE.test(token) && /[.eE]/.test(token)) {
    return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  }
  throw new ParseError(lineNo, `invalid value ${token}`)
}

function parseValue(cur, pathSegs) {
  skipWS(cur)
  const c = cur.line[cur.pos]
  if (c === undefined || c === '#' || c === ';') throw new ParseError(cur.lineNo, 'expected a value')
  if (c === '"') return { kind: 'string', value: parseBasicString(cur) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(cur) }
  if (c === '[') return parseArray(cur, pathSegs)
  if (c === '{') return parseInlineTable(cur, pathSegs)
  if (c === ',' || c === ']' || c === '}') throw new ParseError(cur.lineNo, 'expected a value')
  const start = cur.pos
  while (cur.pos < cur.line.length && !isValueTerminator(cur.line[cur.pos])) cur.pos++
  const token = cur.line.slice(start, cur.pos)
  return interpretBareword(token, cur.lineNo)
}

function parseArray(cur, pathSegs) {
  cur.pos++ // [
  const items = []
  skipWS(cur)
  if (cur.line[cur.pos] === ']') {
    cur.pos++
    return { kind: 'array', items }
  }
  for (;;) {
    const value = parseValue(cur, pathSegs.concat([indexSeg(items.length)]))
    items.push(value)
    skipWS(cur)
    if (cur.line[cur.pos] === ',') {
      cur.pos++
      skipWS(cur)
      if (cur.line[cur.pos] === ']') {
        cur.pos++
        break
      }
      continue
    }
    if (cur.line[cur.pos] === ']') {
      cur.pos++
      break
    }
    throw new ParseError(cur.lineNo, 'unterminated array')
  }
  return { kind: 'array', items }
}

function parseInlineTable(cur, pathSegs) {
  cur.pos++ // {
  const table = newTable()
  skipWS(cur)
  if (cur.line[cur.pos] === '}') {
    cur.pos++
    return table
  }
  for (;;) {
    skipWS(cur)
    const names = parseDottedName(cur)
    skipWS(cur)
    if (cur.line[cur.pos] !== '=') throw new ParseError(cur.lineNo, 'expected = in an inline table')
    cur.pos++
    skipWS(cur)
    const fullPath = pathSegs.concat(names.map(keySeg))
    const { table: container } = walkIntermediate(table, names.slice(0, -1), pathSegs, cur.lineNo)
    const leaf = names[names.length - 1]
    const value = parseValue(cur, fullPath)
    if (container.entries.has(leaf)) {
      throw new ParseError(cur.lineNo, `key ${pathToString(fullPath)} is defined twice`)
    }
    container.entries.set(leaf, value)
    skipWS(cur)
    if (cur.line[cur.pos] === ',') {
      cur.pos++
      continue
    }
    if (cur.line[cur.pos] === '}') {
      cur.pos++
      break
    }
    throw new ParseError(cur.lineNo, 'unterminated inline table')
  }
  return table
}

/**
 * Walks `names` from `table`, creating intermediate tables as needed and
 * following an array of tables to its last element. Returns the table the
 * walk ended on along with the path segments leading to it (including any
 * index segments inserted for arrays of tables), for use by the caller.
 */
function walkIntermediate(table, names, basePathSegs, lineNo) {
  let current = table
  let pathSegs = basePathSegs
  for (const name of names) {
    pathSegs = pathSegs.concat([keySeg(name)])
    const child = current.entries.get(name)
    if (!child) {
      const fresh = newTable()
      current.entries.set(name, fresh)
      current = fresh
    } else if (child.kind === 'table') {
      current = child
    } else if (child.kind === 'aot') {
      const idx = child.items.length - 1
      current = child.items[idx]
      pathSegs = pathSegs.concat([indexSeg(idx)])
    } else {
      throw new ParseError(lineNo, `${pathToString(pathSegs)} is not a table`)
    }
  }
  return { table: current, pathSegs }
}

function handleAssignment(cur, currentTable, currentPathSegs) {
  const names = parseDottedName(cur)
  skipWS(cur)
  if (cur.line[cur.pos] !== '=') throw new ParseError(cur.lineNo, 'expected key = value')
  cur.pos++
  skipWS(cur)
  const { table: container, pathSegs: intermediatePathSegs } = walkIntermediate(
    currentTable,
    names.slice(0, -1),
    currentPathSegs,
    cur.lineNo
  )
  const leaf = names[names.length - 1]
  const fullPathSegs = intermediatePathSegs.concat([keySeg(leaf)])
  const value = parseValue(cur, fullPathSegs)
  skipWS(cur)
  if (cur.pos < cur.line.length) {
    const c = cur.line[cur.pos]
    if (c !== '#' && c !== ';') throw new ParseError(cur.lineNo, 'trailing text after a value')
  }
  if (container.entries.has(leaf)) {
    throw new ParseError(cur.lineNo, `key ${pathToString(fullPathSegs)} is defined twice`)
  }
  container.entries.set(leaf, value)
}

function handleHeader(cur, root, setCurrent) {
  cur.pos++ // [
  let double = false
  if (cur.line[cur.pos] === '[') {
    double = true
    cur.pos++
  }
  const names = parseDottedName(cur)
  skipWS(cur)
  if (cur.line[cur.pos] !== ']') throw new ParseError(cur.lineNo, 'unterminated table header')
  cur.pos++
  if (double) {
    if (cur.line[cur.pos] !== ']') throw new ParseError(cur.lineNo, 'unterminated table header')
    cur.pos++
  }
  skipWS(cur)
  if (cur.pos < cur.line.length) {
    const c = cur.line[cur.pos]
    if (c !== '#' && c !== ';') throw new ParseError(cur.lineNo, 'trailing text after a table header')
  }

  const { table: parent, pathSegs: parentPathSegs } = walkIntermediate(root, names.slice(0, -1), [], cur.lineNo)
  const leaf = names[names.length - 1]
  const leafPathSegs = parentPathSegs.concat([keySeg(leaf)])
  const existing = parent.entries.get(leaf)

  if (!double) {
    let target
    if (!existing) {
      target = newTable()
      target.headerOpened = true
      parent.entries.set(leaf, target)
    } else if (existing.kind === 'table') {
      if (existing.headerOpened) {
        throw new ParseError(cur.lineNo, `table ${pathToString(leafPathSegs)} is defined twice`)
      }
      existing.headerOpened = true
      target = existing
    } else {
      throw new ParseError(cur.lineNo, `${pathToString(leafPathSegs)} is not a table`)
    }
    setCurrent(target, leafPathSegs)
  } else {
    let aot
    if (!existing) {
      aot = { kind: 'aot', items: [] }
      parent.entries.set(leaf, aot)
    } else if (existing.kind === 'aot') {
      aot = existing
    } else {
      throw new ParseError(cur.lineNo, `${pathToString(leafPathSegs)} is not an array of tables`)
    }
    const fresh = newTable()
    fresh.headerOpened = true
    aot.items.push(fresh)
    const idx = aot.items.length - 1
    setCurrent(fresh, leafPathSegs.concat([indexSeg(idx)]))
  }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  let currentTable = root
  let currentPathSegs = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    if (j === line.length) continue
    if (line[j] === '#' || line[j] === ';') continue

    const cur = { line, pos: j, lineNo }
    if (line[cur.pos] === '[') {
      handleHeader(cur, root, (table, segs) => {
        currentTable = table
        currentPathSegs = segs
      })
    } else {
      handleAssignment(cur, currentTable, currentPathSegs)
    }
  }

  return root
}
"}

