  cur.pos++ // [
  const items = []
  skipWS(cur)
  if (cur.line[cur.pos] === ']') {
    cur.pos++
    return { kind: 'array', items }
  }
  for (;;) {
    const value = parseValue(cur, pathSegs.concat([indexSeg(items.length)]))
    items.push(value)
    skipWS(cur)
    if (cur.line[cur.pos] === ',') {
      cur.pos++
      skipWS(cur)
      if (cur.line[cur.pos] === ']') {
        cur.pos++
        break
      }
      continue
    }
    if (cur.line[cur.pos] === ']') {
      cur.pos++
      break
    }
    throw new ParseError(cur.lineNo, 'unterminated array')
  }
  return { kind: 'array', items }
}

function parseInlineTable(cur, pathSegs) {
  cur.pos++ // {
  const table = newTable()
  skipWS(cur)
  if (cur.line[cur.pos] === '}') {
    cur.pos++
    return table
  }
  for (;;) {
    skipWS(cur)
    const names = parseDottedName(cur)
    skipWS(cur)
    if (cur.line[cur.pos] !== '=') throw new ParseError(cur.lineNo, 'expected = in an inline table')
    cur.pos++
    skipWS(cur)
    const fullPath = pathSegs.concat(names.map(keySeg))
    const { table: container } = walkIntermediate(table, names.slice(0, -1), pathSegs, cur.lineNo)
    const leaf = names[names.length - 1]
    const value = parseValue(cur, fullPath)
    if (container.entries.has(leaf)) {
      throw new ParseError(cur.lineNo, `key ${pathToString(fullPath)} is defined twice`)
    }
    container.entries.set(leaf, value)
    skipWS(cur)
    if (cur.line[cur.pos] === ',') {
      cur.pos++
      continue
    }
    if (cur.line[cur.pos] === '}') {
      cur.pos++
      break
    }
    throw new ParseError(cur.lineNo, 'unterminated inline table')
  }
  return table
}

/**
 * Walks `names` from `table`, creating intermediate tables as needed and
 * following an array of tables to its last element. Returns the table the
 * walk ended on along with the path segments leading to it (including any
 * index segments inserted for arrays of tables), for use by the caller.
 */
function walkIntermediate(table, names, basePathSegs, lineNo) {
  let current = table
  let pathSegs = basePathSegs
  for (const name of names) {
    pathSegs = pathSegs.concat([keySeg(name)])
    const child = current.entries.get(name)
    if (!child) {
      const fresh = newTable()
      current.entries.set(name, fresh)
      current = fresh
    } else if (child.kind === 'table') {
      current = child
    } else if (child.kind === 'aot') {
      const idx = child.items.length - 1
      current = child.items[idx]
      pathSegs = pathSegs.concat([indexSeg(idx)])
    } else {
      throw new ParseError(lineNo, `${pathToString(pathSegs)} is not a table`)
    }
  }
  return { table: current, pathSegs }
}

function handleAssignment(cur, currentTable, currentPathSegs) {
  const names = parseDottedName(cur)
  skipWS(cur)
  if (cur.line[cur.pos] !== '=') throw new ParseError(cur.lineNo, 'expected key = value')
  cur.pos++
  skipWS(cur)
  const { table: container, pathSegs: intermediatePathSegs } = walkIntermediate(
    currentTable,
    names.slice(0, -1),
    currentPathSegs,
    cur.lineNo
  )
  const leaf = names[names.length - 1]
  const fullPathSegs = intermediatePathSegs.concat([keySeg(leaf)])
  const value = parseValue(cur, fullPathSegs)
  skipWS(cur)
  if (cur.pos < cur.line.length) {
    const c = cur.line[cur.pos]
    if (c !== '#' && c !== ';') throw new ParseError(cur.lineNo, 'trailing text after a value')
  }
  if (container.entries.has(leaf)) {
    throw new ParseError(cur.lineNo, `key ${pathToString(fullPathSegs)} is defined twice`)
  }
  container.entries.set(leaf, value)
}

function handleHeader(cur, root, setCurrent) {
  cur.pos++ // [
  let double = false
  if (cur.line[cur.pos] === '[') {
    double = true
    cur.pos++
  }
  const names = parseDottedName(cur)
  skipWS(cur)
  if (cur.line[cur.pos] !== ']') throw new ParseError(cur.lineNo, 'unterminated table header')
  cur.pos++
  if (double) {
    if (cur.line[cur.pos] !== ']') throw new ParseError(cur.lineNo, 'unterminated table header')
    cur.pos++
  }
  skipWS(cur)
  if (cur.pos < cur.line.length) {
    const c = cur.line[cur.pos]
    if (c !== '#' && c !== ';') throw new ParseError(cur.lineNo, 'trailing text after a table header')
  }

  const { table: parent, pathSegs: parentPathSegs } = walkIntermediate(root, names.slice(0, -1), [], cur.lineNo)
  const leaf = names[names.length - 1]
  const leafPathSegs = parentPathSegs.concat([keySeg(leaf)])
  const existing = parent.entries.get(leaf)

  if (!double) {
    let target
    if (!existing) {
      target = newTable()
      target.headerOpened = true
      parent.entries.set(leaf, target)
    } else if (existing.kind === 'table') {
      if (existing.headerOpened) {
        throw new ParseError(cur.lineNo, `table ${pathToString(leafPathSegs)} is defined twice`)
      }
      existing.headerOpened = true
      target = existing
    } else {
      throw new ParseError(cur.lineNo, `${pathToString(leafPathSegs)} is not a table`)
    }
    setCurrent(target, leafPathSegs)
  } else {
    let aot
    if (!existing) {
      aot = { kind: 'aot', items: [] }
      parent.entries.set(leaf, aot)
    } else if (existing.kind === 'aot') {
      aot = existing
    } else {
      throw new ParseError(cur.lineNo, `${pathToString(leafPathSegs)} is not an array of tables`)
    }
    const fresh = newTable()
    fresh.headerOpened = true
    aot.items.push(fresh)
    const idx = aot.items.length - 1
    setCurrent(fresh, leafPathSegs.concat([indexSeg(idx)]))
  }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  let currentTable = root
  let currentPathSegs = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    if (j === line.length) continue
    if (line[j] === '#' || line[j] === ';') continue

    const cur = { line, pos: j, lineNo }
    if (line[cur.pos] === '[') {
      handleHeader(cur, root, (table, segs) => {
        currentTable = table
        currentPathSegs = segs
      })
    } else {
      handleAssignment(cur, currentTable, currentPathSegs)
    }
  }

  return root
}
"}

