      const lines = keys.map((k) => `${inner}${jsonString(k)}: ${jsonValue(node.entries.get(k), inner)}`)
      return `{\n${lines.join(',\n')}\n${indent}}`
    }
    case 'aot':
      return jsonArrayLike(node.items, indent)
    case 'array':
      return jsonArrayLike(node.items, indent)
    case 'string':
      return jsonString(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value
    case 'float':
      return String(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
